# Проверяем числа n, n + 1, n + 2, ... по очереди, пока не встретим простое.
# Проверка на простоту перебирает возможные делители только до корня: d * d <= x.
# Простые числа встречаются часто, поэтому проверять придётся совсем немного чисел.
def is_prime(x):
    if x < 2:
        return False
    d = 2
    while d * d <= x:
        if x % d == 0:
            return False
        d += 1
    return True


n = int(input())
while not is_prime(n):
    n += 1
print(n)

