# Клетка в строке i и столбце j (нумерация с нуля) чёрная, если i + j чётно:
# при шаге вправо или вниз сумма меняется на 1, и цвет чередуется.
n, m = map(int, input().split())
for i in range(n):
    row = ""
    for j in range(m):
        if (i + j) % 2 == 0:
            row += "#"
        else:
            row += "."
    print(row)

# Считаем частоты букв в s и в t. Для каждой буквы слова t копий получится не больше,
# чем (сколько таких букв в s) // (сколько их нужно на одно слово).
# Ответ – наименьшее из этих чисел по всем буквам слова t.
s = input().strip()
t = input().strip()
have = {}
for ch in s:
    have[ch] = have.get(ch, 0) + 1
need = {}
for ch in t:
    need[ch] = need.get(ch, 0) + 1
answer = len(s)
for ch in need:
    answer = min(answer, have.get(ch, 0) // need[ch])
print(answer)

# Первое вхождение x – это первая позиция, где число не меньше x.
# Последнее вхождение стоит прямо перед первой позицией, где число не меньше x + 1.
# Обе позиции находим двоичным поиском: запросов много, а каждый обрабатывается примерно за 17 шагов.
def first_not_less(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


n = int(input())
a = list(map(int, input().split()))
q = int(input())
for x in map(int, input().split()):
    left = first_not_less(a, x)
    right = first_not_less(a, x + 1)
    if left < right:
        print(left + 1, right)
    else:
        print(0, 0)

