# Для каждой пустой клетки перебираем сдвиги di и dj от -1 до 1 (кроме 0, 0),
# проверяем, что сосед не выходит за поле, и считаем мины.
# Результат собираем в новую строку, не меняя исходное поле.
n, m = map(int, input().split())
grid = [input().strip() for _ in range(n)]
for i in range(n):
    row = ""
    for j in range(m):
        if grid[i][j] == "*":
            row += "*"
            continue
        mines = 0
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                ni, nj = i + di, j + dj
                if (di, dj) != (0, 0) and 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == "*":
                    mines += 1
        row += str(mines)
    print(row)

